#include <iostream>
#include <memory>
#include <utility>
#include <new>

class Tramo {
public:
    Tramo() = default;
    Tramo(const Tramo& otra);
    Tramo& operator=(const Tramo& otra);
    Tramo(Tramo&& otra) noexcept;
    Tramo& operator=(Tramo&& otra) noexcept;
    ~Tramo() = default;
    int cantidad() const noexcept { return cantidad_; }
    const int* acceso() const noexcept { return datos_.get(); }
    bool configurar(int cantidad) noexcept;
    bool leer(int indice, int& resultado) const noexcept;
    bool escribir(int indice, int valor) noexcept;
    bool vaciar() noexcept;
    int sumar() const noexcept;
    void intercambiar(Tramo& otra) noexcept;
private:
    std::unique_ptr<int[]> datos_{};
    int cantidad_ = 0;
};
Tramo::Tramo(const Tramo& otra) : datos_{}, cantidad_{0} {
    if (otra.cantidad_ != 0) {
        datos_ = std::make_unique<int[]>(otra.cantidad_);
        for (int i = 0; i < otra.cantidad_; ++i) {
            datos_[i] = otra.datos_[i];
        }
        cantidad_ = otra.cantidad_;
    }
}

bool Tramo::configurar(int cantidad) noexcept {
    if (cantidad < 0 || cantidad > 4) {
        return false;
    }
    if (cantidad == 0) {
        return vaciar();
    }
    try {
        auto candidata = std::make_unique<int[]>(cantidad);
        datos_.swap(candidata);
        cantidad_ = cantidad;
        return true;
    } catch (const std::bad_alloc&) {
        return false;
    }
}

bool Tramo::leer(int indice, int& resultado) const noexcept {
    if (indice < 0 || indice >= cantidad_) {
        return false;
    }
    resultado = datos_[indice];
    return true;
}

bool Tramo::escribir(int indice, int valor) noexcept {
    if (indice < 0 || indice >= cantidad_ || valor < 0 || valor > 9) {
        return false;
    }
    datos_[indice] = valor;
    return true;
}

bool Tramo::vaciar() noexcept {
    datos_.reset();
    cantidad_ = 0;
    return true;
}

int Tramo::sumar() const noexcept {
    int suma = 0;
    for (int i = 0; i < cantidad_; ++i) {
        suma += datos_[i];
    }

    return suma;
}

void Tramo::intercambiar(Tramo& otra) noexcept {
    datos_.swap(otra.datos_);
    std::swap(cantidad_, otra.cantidad_);
}

void mostrar(const Tramo& lote) {
    std::cout << lote.cantidad() << '[';
    for (int i = 0; i < lote.cantidad(); ++i) {
        int valor = -1;
        lote.leer(i, valor);
        if (i != 0) {
            std::cout << ',';
        }
        std::cout << valor;
    }
    std::cout << ']';
}

int main() {
    Tramo a;
    if (!a.configurar(3)) { return 1; }
    a.escribir(0, 2); a.escribir(2, 5);
    Tramo b{a};
    b.escribir(0, 9);
    mostrar(a); std::cout << ':'; mostrar(b);
    return 0;
}

